CREATE TEMPORARY VIEW vitem_cspu_${grass_region_without_quote} AS
select
     cspu_id
    ,vitem_id
    ,exp_tag
from(
    SELECT -- current all vitemid-cspuid
         vitem_id
        ,cspu_id
    FROM srdi_mart.dim_sr_data_warehouse_vsku_model_mapping_hf
    where grass_region in (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
    group by
         vitem_id
        ,cspu_id
) a
lateral view explode(array('T1','T2','T3','T5')) b as exp_tag -- 按照实验策略数量，进行维表复制拷贝，v3的第一次发版只有一个实验策略
where (
case
  when ${grass_region} in ('TH') then exp_tag in ('T1','T2','T3')
  when ${grass_region} in ('VN','MY') then exp_tag in ('T1','T2')
  when ${grass_region} in ('PH') then exp_tag in ('T1','T2','T5')
  when ${grass_region} in ('BR','TW') then exp_tag in ('T1')
  else false
end
)
;
--sql_divide_splitter--
-- 获取最近7天，最大可用且<当前小时的分区，以此获取上一个可用的历史分区，还会外加质量检测：>10%的版本日期=（当日+昨日）就报错
-- 兜底设计：如果是稳定性问题，7*24个机会极大概率会有一个成功的；如果真的7天不成功，但是7天后成功，就依赖DQC拦截。
set last_partition_${grass_region_without_quote} = (
select
    max(time_str)
from(
    SELECT
        concat(regional_date,'_',if(regional_hour<10,concat('0',regional_hour),regional_hour)) as  time_str
    FROM srdi_mart.dim_sr_data_warehouse_vsku_replace_status_hf
    where grass_region in (${grass_region}) and regional_date between date_sub(${regional_date}, 6) and ${regional_date}
    group by regional_date,regional_hour
) a
where time_str<concat(${regional_date},'_',if(${regional_hour}<10,concat('0',${regional_hour}),${regional_hour}))
);
--sql_divide_splitter--

CREATE TEMPORARY VIEW last_vitem_cspu_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,vitem_id
    ,cspu_id
    ,vitem_status
    ,is_qualified
    ,version_date
    ,filtered_reason
FROM srdi_mart.dim_sr_data_warehouse_vsku_replace_status_hf
where grass_region in (${grass_region}) and regional_date = split(${last_partition_${grass_region_without_quote}},'_')[0]
and regional_hour = cast(split(${last_partition_${grass_region_without_quote}},'_')[1] as int)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW accumulated_vitem_cspu_${grass_region_without_quote} AS
SELECT
     if(a.vitem_id is not null ,a.vitem_id,b.vitem_id) as vitem_id
    ,if(a.cspu_id is not null ,a.cspu_id,b.cspu_id) as cspu_id
    ,if(a.exp_tag is not null ,a.exp_tag,b.exp_tag) as exp_tag
FROM last_vitem_cspu_${grass_region_without_quote} a
full outer join vitem_cspu_${grass_region_without_quote} b on a.vitem_id=b.vitem_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag
;
--sql_divide_splitter--
-- 相较于cheapest，当前vitem的版本和回退是发生在vitem level的，所以需要额外聚合一下，防止新增rmodelid导致出现额外版本
CREATE TEMPORARY VIEW last_vitem_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,vitem_id --因为是质检和版本都是vitemidlevel的，所以max应该没有抛弃啥值
    ,max(vitem_status) as vitem_status
    ,max(is_qualified) as is_qualified -- 0、1、null，max=1，min=0，字符串类型的int也同样适用。
    ,max(version_date) as version_date
    ,max(filtered_reason) as filtered_reason
FROM last_vitem_cspu_${grass_region_without_quote}
group by
     exp_tag
    ,vitem_id
;
--sql_divide_splitter--
-- 这里不取最大可用分区，也不依赖marker，如果错过了就需要上游重新装填，但是99%不会错过的，除非你总是23点附近产出。
