INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_vsku_replace_status_hf
partition(grass_region = ${grass_region}, local_date, local_hour, regional_date,regional_hour)
SELECT
     vitem_id
    ,cspu_id
    ,if(update_flag
        ,case
           when new_is_qualified=0 then 'filtered'  --不过质检就是filtered
           when new_is_qualified=1 then 'explore'   --通过质检就是explore
           else 'prepare' --质检不明就是prepare
         end
        ,current_vitem_status -- 如果不是，维护其原本的状态
     ) as vitem_status
    ,0 as is_exempted  -- phase 1 don't involve MPI ，so set fixed value 1
    ,if(update_flag
        ,new_is_qualified
        ,current_is_qualified
      ) as is_qualified
    ,if(update_flag
       ,if(new_is_qualified is not null
          ,replace(${regional_date}, '-', '')
          ,null --没有的等待质检信息
          )
       ,current_version_date
     ) as version_date --版本信息是线上流转的关键信息之一。
    ,if(update_flag
       ,new_filtered_reason
       ,current_filtered_reason
     ) as filtered_reason --质检不通过的具体原因，一期离线只会给出质检不过的4种原因
    ,exp_tag

    ,date(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"yyyy-MM-dd")) as local_date
    ,cast(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"HH") as int) as local_hour
    ,cast(${regional_date} as date) as regional_date
    ,cast(${regional_hour} as int) as regional_hour
from(
    select
         a.exp_tag
        ,a.vitem_id
        ,a.cspu_id
        ,if( (c.new_version_date is not null and c.new_version_date > coalesce(d.version_date,0)) --需要版本升级的；截止20250903的需求逻辑，如果new_version_date不是null，那么d.version_date理论也不会是null
             or
             (d.version_date is null) --这里其实包含两种：1）本次运行新补充的；2）上次运行没有质检信息的
            ,true
            ,false
         ) as update_flag
        ,d.vitem_status as current_vitem_status
        ,d.is_qualified as current_is_qualified
        ,d.version_date as current_version_date
        ,d.filtered_reason as current_filtered_reason
        ,1 as new_is_qualified
        ,c.new_version_date as new_version_date
        ,'sucess' as new_filtered_reason -- 因为原表是拼写错误，这里继续维持拼写错误，以免影响下游使用
    from accumulated_vitem_cspu_${grass_region_without_quote} a
--    left join qualify_label_${grass_region_without_quote} b on a.vitem_id=b.vitem_id
    left join version_label_${grass_region_without_quote} c on a.vitem_id=c.vitem_id and a.exp_tag=c.exp_tag
    left join last_vitem_${grass_region_without_quote} d on a.vitem_id=d.vitem_id and a.exp_tag=d.exp_tag
) e
;
